-- Reglas de capas (layer-shell)
-- NOTA: el conversor tenía un bug aquí (metía literalmente "match:namespace ..."
-- como valor del campo namespace, en vez de solo el regex) - corregido a mano.
-- El campo "blur" (bool plano) está CONFIRMADO: probado con
-- `Hyprland --config hyprland.lua --verify-config` en 0.56.2, que sí detecta
-- nombres de campo inventados ("unknown field") - blur pasó limpio.
hl.layer_rule({
    match = { namespace = "^(swaync-control-center)$" },
    blur = true,
})

hl.layer_rule({
    match = { namespace = "^(rofi)$" },
    blur = false,
})

-- media-card.py es GtkLayerShell con fondo rgba (0.92) - mismo bug de blur+alpha
-- en NVIDIA que control-center: con blur true se ve un borde rectangular feo
-- alrededor de las esquinas redondeadas (confirmado por Tara 2026-09-08, mismo
-- síntoma que se preveía en la nota original de 2026-08-26). Quitado el blur,
-- igual que se hizo con control-center el mismo día que se encontró el bug.

-- Reglas de ventanas
hl.window_rule({
    match = {
        class = "^(xfreerdp)$",
    },
    workspace = "9",
})

-- "silent" no aparece documentado en ningún sitio para el campo workspace de
-- window_rule. `--verify-config` acepta el string tal cual (workspace es solo
-- un campo "string", no valida su contenido), así que esto NO confirma que
-- Hyprland interprete "silent" de verdad - solo que el texto es sintácticamente
-- válido. Falta probarlo en vivo (¿se mueve sin cambiar de escritorio, o no?).
hl.window_rule({
    match = {
        class = "^(rdp-console)$",
    },
    workspace = "special:minimized silent",
})

hl.window_rule({
    match = {
        class = "^notarapida$",
    },
    float = true,
    size = "700 480",
    center = true,
})

hl.window_rule({
    match = {
        class = "^xfce-polkit$",
    },
    float = true,
    size = "520 143",
    center = true,
})

hl.window_rule({
    match = {
        class = "^(fsearch|io.github.cboxdoerfer.FSearch)$",
    },
    float = true,
    size = "850 550",
    center = true,
})

hl.window_rule({
    match = {
        title = "^(.*(Abrir archivo|Guardar como|Open File|Save As|Confirmar|Confirm|Elección de archivo|Sign in - Google Accounts|Iniciar sesión).*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(xdg-desktop-portal.*|zenity|pavucontrol|blueman-manager)$",
    },
    float = true,
})

-- Picture-in-Picture de Firefox: flotante, fijada sobre todo y en la esquina
-- inferior derecha (para seguir una clase mientras trabajas en otra ventana).
hl.window_rule({
    match = {
        title = "^(Picture-in-Picture)$",
