-- Modo RDP: rdp-mode-watch.py activa este submap automaticamente en
-- cuanto la ventana xfreerdp coge el foco (y lo quita al perderlo), asi
-- las teclas viajan directas a Windows sin tener que pulsar nada antes.
-- Excepciones que se quedan en Hyprland: SUPER+Q (matar la ventana si
-- se cuelga) y ALT+numeros/flechas (cambiar de escritorio). Control_r
-- es un escape manual por si el vigia se cae.
hl.define_submap("rdp", function()
    hl.bind("control_r", hl.dsp.submap("reset"))
    hl.bind("control_r", hl.dsp.exec_cmd("/home/tara/.local/bin/rdp-mode.sh off"))
    hl.bind(mainMod .. " + Q", hl.dsp.window.close())
    hl.bind("ALT + 1", hl.dsp.focus({ workspace = 1 }))
    hl.bind("ALT + 2", hl.dsp.focus({ workspace = 2 }))
    hl.bind("ALT + 3", hl.dsp.focus({ workspace = 3 }))
    hl.bind("ALT + 4", hl.dsp.focus({ workspace = 4 }))
    hl.bind("ALT + 5", hl.dsp.focus({ workspace = 5 }))
    hl.bind("ALT + 6", hl.dsp.focus({ workspace = 6 }))
    hl.bind("ALT + 7", hl.dsp.focus({ workspace = 7 }))
    hl.bind("ALT + 8", hl.dsp.focus({ workspace = 8 }))
    hl.bind("ALT + 9", hl.dsp.focus({ workspace = 9 }))
    hl.bind("ALT + right", hl.dsp.focus({ workspace = "e+1" }))
    hl.bind("ALT + left", hl.dsp.focus({ workspace = "e-1" }))
end)

